svg.script:
//
const stepData = [
  {
    title: "1. INCAPACIDADE COMUNICATIVA",
    subtitle: "ETAPA 1: O Silêncio Fisiológico",
    desc: "O paciente idoso apresenta afasia, demência avançada ou sequela de AVC que impede a expressão verbal das suas necessidades. Embora a via sensorial de sede esteja íntegra, a incapacidade mecânica de comunicar o bloqueia. É o ponto de partida do ciclo clínico.",
    vitals: [
      { label: "Status de Comunicação", value: "Déficit Grave", status: "red" },
      { label: "Sódio Sérico (Na+)", value: "140 mEq/L (Normal)", status: "green" },
      { label: "CAM-ICU (Delirium)", value: "Ausente", status: "green" }
    ],
    prevention: "Identificar o déficit de comunicação na admissão e instituir rotina de oferta ativa e supervisionada de líquidos a cada 2h (não espere o paciente pedir).",
    gaugeWidth: "60",
    gaugeColor: "neutral"
  },
  {
    title: "2. PRIVACÃO SILENCIOSA (SEDE)",
    subtitle: "ETAPA 2: A Sede Invisível",
    desc: "Sem conseguir manifestar a necessidade de líquidos, o idoso passa horas em balanço hídrico negativo. Em idosos, a própria sensibilidade de sede do hipotálamo está atenuada (hipodipsia senil), dificultando a percepção da gravidade pela equipe cuidadora.",
    vitals: [
      { label: "Ingestão Hídrica", value: "Nula", status: "red" },
      { label: "Mucosas / Boca", value: "Secas / Fissuradas", status: "amber" },
      { label: "Balanço Hídrico", value: "Negativo", status: "amber" }
    ],
    prevention: "Uso de ferramentas visuais (quadros de metas hídricas no leito) e pesagem diária para detectar perda de fluido de forma objetiva.",
    gaugeWidth: "120",
    gaugeColor: "amber"
  },
  {
    title: "3. DESIDRATACÃO INSTAURADA",
    subtitle: "ETAPA 3: O Limiar de Descompensação",
    desc: "A privação prolongada evolui com hemoconcentração e hipernatremia (concentração elevada de sódio plasmático). A redução do volume circulante gera hipoperfusão sistêmica leve e retração do volume intracelular neuronal. O paciente aproxima-se da falência funcional cerebral.",
    vitals: [
      { label: "Sódio Sérico (Na+)", value: "148 mEq/L (Elevado)", status: "orange" },
      { label: "Osmolaridade Sérica", value: "310 mOsm/kg (Alta)", status: "orange" },
      { label: "Turgor Cutâneo", value: "Diminuído", status: "amber" }
    ],
    prevention: "Coleta imediata de eletrólitos e início de hidratação oral lenta assistida ou infusão subcutânea (hipodermóclise) para evitar oscilação rápida do sódio.",
    gaugeWidth: "180",
    gaugeColor: "orange"
  },
  {
    title: "4. DELIRIUM / EMERGÊNCIA",
    subtitle: "ETAPA 4: A Falência Cognitiva Aguda",
    desc: "A hiperosmolaridade celular causa desidratação dos neurônios, induzindo disfunção nas vias de acetilcolina e dopamina. Instala-se o Delirium (flutuação de consciência, desatenção grave), que dobra a mortalidade intrahospitalar e prolonga o tempo de internação.",
    vitals: [
      { label: "Cognição (CAM-ICU)", value: "Positivo (Delirium)", status: "red" },
      { label: "Sódio Sérico (Na+)", value: "155 mEq/L (Crítico)", status: "red" },
      { label: "Estado de Consciência", value: "Flutuante / Sonolento", status: "red" }
    ],
    prevention: "Tratar a causa base (hidratação). Evitar sedativos ou contenção mecânica, que agravam o delirium. Monitorar balanço eletrolítico de hora em hora.",
    gaugeWidth: "310",
    gaugeColor: "red"
  },
  {
    title: "5. RECUPERACÃO CLÍNICA",
    subtitle: "ETAPA 5: O Desfecho Terapêutico",
    desc: "A instituição de terapia de reposição hídrica controlada restaura a volemia e normaliza os níveis de sódio plasmático. A reidratação neuronal restabelece a homeostase sináptica, levando à remissão do delirium e retorno do paciente ao estado cognitivo basal.",
    vitals: [
      { label: "Sódio Sérico (Na+)", value: "141 mEq/L (Normal)", status: "green" },
      { label: "CAM-ICU (Delirium)", value: "Negativo (Revertido)", status: "green" },
      { label: "Nível de Consciência", value: "Alerta e Orientado", status: "green" }
    ],
    prevention: "Desenhar plano de transição de cuidados com orientações aos familiares sobre monitoramento hídrico e sinais iniciais de desidratação após a alta.",
    gaugeWidth: "60",
    gaugeColor: "green"
  }
];

function selectStep(stepIndex) {
  // 1. Toggle active classes on cards
  for (let i = 1; i <= 5; i++) {
    const card = document.getElementById('step-card-' + i);
    if (card) {
      if (i === stepIndex) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
      }
    }
  }

  // 2. Load step data
  const data = stepData[stepIndex - 1];
  if (!data) return;

  // 3. Update Text Content in Reading Panel
  document.getElementById('panel-step-title').textContent = data.title;
  document.getElementById('panel-step-subtitle').textContent = data.subtitle;
  document.getElementById('panel-step-subtitle').setAttribute('fill', 'var(--piso-' + data.gaugeColor + ')');

  // Helper to wrap text into 4 lines
  const descLines = wrapText(data.desc, 64);
  for (let i = 1; i <= 4; i++) {
    const tspan = document.getElementById('panel-desc-l' + i);
    if (tspan) {
      tspan.textContent = descLines[i - 1] || "";
    }
  }

  // Helper to wrap prevention text into 3 lines
  const prevLines = wrapText(data.prevention, 72);
  for (let i = 1; i <= 3; i++) {
    const tspan = document.getElementById('panel-prev-l' + i);
    if (tspan) {
      tspan.textContent = prevLines[i - 1] || "";
    }
  }

  // 4. Update Clinical Parameters
  for (let i = 0; i < 3; i++) {
    const param = data.vitals[i];
    const dot = document.getElementById('param-' + (i + 1) + '-dot');
    const label = document.getElementById('param-' + (i + 1) + '-label');
    const value = document.getElementById('param-' + (i + 1) + '-value');

    if (dot && label && value) {
      dot.setAttribute('class', 'param-dot status-' + param.status);
      label.textContent = param.label;
      value.textContent = param.value;
      value.setAttribute('fill', 'var(--piso-' + (param.status === 'green' ? 'text-primary' : param.status) + ')');
    }
  }

  // 5. Update Danger Gauge Bar
  const gauge = document.getElementById('alert-gauge');
  if (gauge) {
    gauge.setAttribute('width', data.gaugeWidth);
    gauge.setAttribute('fill', 'var(--piso-' + data.gaugeColor + ')');
  }

  // 6. Connectors logic: highlight route up to selected index
  for (let i = 1; i <= 4; i++) {
    const arrow = document.getElementById('arrow-to-5');
    if (stepIndex === 5 && arrow) {
      arrow.classList.add('active');
      arrow.setAttribute('stroke', 'var(--piso-green)');
    } else if (arrow) {
      arrow.classList.remove('active');
      arrow.removeAttribute('stroke');
    }
  }
}

// Wrap utility
function wrapText(text, maxChars) {
  const words = text.split(' ');
  const lines = [];
  let currentLine = "";

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if ((currentLine + " " + word).trim().length <= maxChars) {
      currentLine = (currentLine + " " + word).trim();
    } else {
      lines.push(currentLine);
      currentLine = word;
    }
  }
  if (currentLine) {
    lines.push(currentLine);
  }
  return lines;
}

// Initialize with first step
selectStep(1);
//
